    "same oracle collision symptom must occur",
    "ego must have nonzero speed shortly before collision",
    "a nearby actor must be present according to perception/prediction before collision",
    "final_waypoints must remain available and not marked as blocked before the collision",
    "vehicle_cmd must remain effectively zero while ego continues to move"
  ],
  "uncertainty": [
    "Module-level attribution is unclear because perception detects objects, prediction produces trajectories, planning publishes unblocked waypoints, yet vehicle_cmd is all zero while vehicle_status shows motion.",
    "The discrepancy between closest_object_distance=0.0 in final_waypoints summary and 3.486 m distance in oracle objects is not explained by the evidence.",
    "The data does not reveal whether the collision resulted from perception mislocalization, planning decisions, controller behavior, or simulator/vehicle interface issues."
  ],
  "evidence_support": [
    {
      "evidence_id": "oracle_error_json_events",
      "claim": "The oracle reports a crash event with no stuck, lane invasion, or red-light violations."
    },
    {
      "evidence_id": "collision_window_ego_speed_before_collision",
      "claim": "Ego speed in the collision window reaches about 4.94 m/s with last pre-collision speed 4.70 m/s and no speed decrease indicating braking."
    },
    {
      "evidence_id": "collision_window_evidence_of_braking_or_stopping",
      "claim": "Both vehicle_status and vehicle_cmd report zero brake, and there is no observed speed decrease within the window."
    },
    {
      "evidence_id": "trace_summary_perception_detection_objects",
      "claim": "Detection objects exist throughout the run, with at least one object detected and labels including car and unknown."
    },
    {
      "evidence_id": "trace_summary_perception_prediction_objects",
      "claim": "Prediction objects exist with 1–23 predicted objects per message and labels including car and unknown in the time leading to the collision."
    },
    {
      "evidence_id": "critical_window_final_waypoints_before_collision",
      "claim": "Final waypoints are continuously available with 101 waypoints and no blocked flags prior to collision; closest_object_distance is summarized as 0.0 at the nearest pre-collision row."
    },
    {
      "evidence_id": "closest_available_object_info",
      "claim": "The oracle collision data reports a closest available object (id 10283, classification 6) at a distance of 3.486 m from the ego before the collision."
    },
    {
      "evidence_id": "collision_topic_objects_sample",
      "claim": "The oracle collision topic lists other_actor_ids including 10283 with a wide range of impulse magnitudes, indicating an actual collision with that actor."
    },
    {
      "evidence_id": "trace_summary_actuation_vehicle_cmd",
      "claim": "The vehicle_cmd topic exists, but accel_cmd, brake_cmd, steer_cmd, and target_speed ranges remain at zero from 10.23s to 21.13s."
    },
    {
      "evidence_id": "trace_summary_actuation_vehicle_status",
      "claim": "Vehicle_status shows ego velocity ranging from 0.0 to 9.75 m/s and nonzero throttle values, indicating that the vehicle moves despite all-zero vehicle_cmd."
    }
  ],
  "confidence": "medium",
  "ready_for_phase2_generation": "yes",
  "notes_for_validator": [
    "Verify that the oracle collision topic in the generated case confirms a collision between ego and at least one non-ego actor near the end of the run.",
    "Check that ego velocity from vehicle_status or odometry is nonzero and does not significantly decrease due to braking within several seconds before the collision.",
    "Confirm that detection and prediction object topics are populated and show at least one actor near ego in the critical window.",
    "Ensure final_waypoints are present with a consistent waypoint count and no blocked flags before the collision event.",
    "Confirm that vehicle_cmd accel_cmd, brake_cmd, steer_cmd, and target_speed remain effectively zero while vehicle_status indicates ego motion, reproducing the command–status mismatch pattern."
  ]
}

